(6629935, 989778, 94265, '<td valign="top">Love the styling, her eye make-up is nice and his expression is funny; I''m not keen on the close crop though, would''ve liked it to be a little further out to see more of their body language. Different lighting would have helped this for me I think, something a little softer and brighter, just a personal thought.</td>', 'Love the styling, her eye make-up is nice and his expression is funny; I''m not keen on the close crop though, would''ve liked it to be a little further out to see more of their body language. Different lighting would have helped this for me I think, something a little softer and brighter, just a personal thought.', '2012-01-01 11:39:41.000000', NULL, 1),
(6629936, 989911, 113156, '<td valign="top">A portal to another dimension, i might have been tempted to take the plunge. Lovely and interesting black &amp; white.</td>', 'A portal to another dimension, i might have been tempted to take the plunge. Lovely and interesting black & white.', '2012-01-01 11:41:13.000000', NULL, 1),
(6629937, 990602, 94265, '<td valign="top">Nice warm tones to this, quite an amusing scene really but I so wish the birds on the ground were in clearer focus; I feel this could have been a lot better with more sharpening.</td>', 'Nice warm tones to this, quite an amusing scene really but I so wish the birds on the ground were in clearer focus; I feel this could have been a lot better with more sharpening.', '2012-01-01 11:41:36.000000', NULL, 1),
(6629940, 990590, 94265, '<td valign="top">Very cute idea and nice colours but I so wish we could see ears or eyes or something more of the kitty than just the paw. It is cute but I feel that would really have made the picture. Could do with a wee bit of denoising too.</td>', 'Very cute idea and nice colours but I so wish we could see ears or eyes or something more of the kitty than just the paw. It is cute but I feel that would really have made the picture. Could do with a wee bit of denoising too.', '2012-01-01 11:47:54.000000', NULL, 1),
(6629941, 989892, 94265, '<td valign="top">Interesting little place, looks like there could be some lovely reds and greens going on, would''ve loved to see this in full daylight.</td>', 'Interesting little place, looks like there could be some lovely reds and greens going on, would''ve loved to see this in full daylight.', '2012-01-01 11:48:37.000000', NULL, 1),
(6629942, 990557, 94265, '<td valign="top">Good focus and sharpness. I like the contrast of the weathered older hands and the shiny fancy jewellery.</td>', 'Good focus and sharpness. I like the contrast of the weathered older hands and the shiny fancy jewellery.', '2012-01-01 11:50:42.000000', NULL, 1),
(6629943, 990609, 94265, '<td valign="top">Beautiful scenery and sky. A little frontal bokeh would''ve been nice for me. Great colours.</td>', 'Beautiful scenery and sky. A little frontal bokeh would''ve been nice for me. Great colours.', '2012-01-01 11:52:02.000000', NULL, 1),
(6629944, 990567, 94265, '<td valign="top">Very pretty doll, nice crisp focus. That one big hair curling in front of her face is a bit distracting, I''d probably have cloned that out of the way. Nice shot overall.</td>', 'Very pretty doll, nice crisp focus. That one big hair curling in front of her face is a bit distracting, I''d probably have cloned that out of the way. Nice shot overall.', '2012-01-01 11:53:52.000000', NULL, 1),
(6629946, 990322, 94265, '<td valign="top">Interesting place, I''m not usually daft on this processing but it works here. Nicely lit.</td>', 'Interesting place, I''m not usually daft on this processing but it works here. Nicely lit.', '2012-01-01 11:54:44.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6629948, 989951, 94265, '<td valign="top">I like the perspective, fantastic colours, nice to see something different. Nice crisp focus too, very good shot.</td>', 'I like the perspective, fantastic colours, nice to see something different. Nice crisp focus too, very good shot.', '2012-01-01 11:56:12.000000', NULL, 1),
(6629952, 989636, 94265, '<td valign="top">I feel the red saturation is up a bit much on the child''s face, makes it look a bit strange, the red dot on the hat also grabs my eye which is a shame as I love the rest of the shot. Lovely location and angle, nice light, good focus and bokeh; great shot except for the facial processing. Denoising a little might have helped.</td>', 'I feel the red saturation is up a bit much on the child''s face, makes it look a bit strange, the red dot on the hat also grabs my eye which is a shame as I love the rest of the shot. Lovely location and angle, nice light, good focus and bokeh; great shot except for the facial processing. Denoising a little might have helped.', '2012-01-01 11:59:56.000000', NULL, 1),
(6629956, 990589, 94265, '<td valign="top">Very pretty scene, nice colours and good exposure; I might have chosen a different vantage point though, the blue of the sky is gorgeous and it seems a shame to have obstructed it with the branches.</td>', 'Very pretty scene, nice colours and good exposure; I might have chosen a different vantage point though, the blue of the sky is gorgeous and it seems a shame to have obstructed it with the branches.', '2012-01-01 12:01:00.000000', NULL, 1),
